enum TpdfStatus tpdf_outline_item(const struct TpdfOutline *outline,
                                  uint32_t index,
                                  uint32_t *out_depth,
                                  int *out_open);

// One entry's title, decoded. The caller frees it with
// [`crate::tpdf_string_free`].
//
// # Safety
//
// `outline` must be a live handle and `out` a valid pointer.
enum TpdfStatus tpdf_outline_title(const struct TpdfOutline *outline, uint32_t index, char **out);

// Where one entry goes. [`TpdfDestinationKind::Absent`] is an entry that is
